public function finalize(string $paypalOrderId): Payment
{
    $capture = $this->paypal->captureOrder($paypalOrderId);

    return DB::transaction(function () use ($capture) {
        $payment = Payment::where('provider_ref', $capture->id)
            ->lockForUpdate()
            ->firstOrFail();

        if ($payment->status === 'captured') {
            return $payment; // idempotent retry
        }

        $payment->update([
            'status'      => 'captured',
            'amount'      => $capture->amount,
            'captured_at' => now(),
        ]);

        $payment->listing->markAsPaid();
        return $payment;
    });
}

it('issues a termin invoice only once per milestone', function () {
    $contract = Contract::factory()
        ->withTerminPlan([30, 40, 30])
        ->create();

    $first  = app(InvoiceService::class)->issueTermin($contract, 1);
    $second = app(InvoiceService::class)->issueTermin($contract, 1);

    expect($first->id)->toBe($second->id)
        ->and($contract->invoices()->count())->toBe(1)
        ->and($first->amount)->toBe('3000000.00');
});

it('rejects a termin beyond the contract total', function () {
    $contract = Contract::factory()->fullyInvoiced()->create();

    app(InvoiceService::class)->issueTermin($contract, 4);
})->throws(InvalidTerminException::class);

